1	/**
2	 * Record the migrated closure and the one production build attempt made on it.
3	 *
4	 * mj1 left this cell red at the install: the migrated manifest asked for an
5	 * Angular 16.2 closure whose community layer still carried Angular 13 peers, and
6	 * npm refused it before fetching a single tarball. The cell now declares that
7	 * layer, so this driver records two things mj1 could not: that the closure
8	 * resolves and installs, and what the compiler then demands.
9	 *
10	 * The build is recorded as it happened. It is red, and the value of the record
11	 * is the itemisation: every demand the compiler made, by file, by symbol and by
12	 * the library that moved under it. That list is the input to the next unit. It
13	 * is not a defect list and it is not a failure report — a build that has not yet
14	 * been given its source transforms is expected to ask for them.
15	 *
16	 * The driver is fixture-scoped: it knows where this fixture's closure was
17	 * staged. Every decision about *what to change* lives in `@versionless/angular`,
18	 * which knows nothing about this application.
19	 */
20	
21	import { readFile, mkdir, writeFile } from 'node:fs/promises';
22	import * as path from 'pathe';
23	import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
24	import { CONSENT_ID, MIGRATION_RECORD_FILE } from './angular-jira-clone-migration-run.ts';
25	
26	const repositoryRoot = path.resolve(import.meta.dirname, '../../../..');
27	const evidenceDirectory = path.join(repositoryRoot, 'evidence/runs/angular-jira-clone');
28	
29	export const STAGE_DIRECTORY = path.join(
30		repositoryRoot,
31		'.versionless/stage/angular-jira-clone-mj2',
32	);
33	
34	export const UNIT = 'lrapr-t005/mj2-ecosystem-cell-closure';
35	export const CLOSURE_RECORD_FILE = 'mj2-migrated-closure.json';
36	export const ACQUISITION_RECORD_FILE = 'mj2-acquired-closure.json';
37	
38	/**
39	 * What this record replaces.
40	 *
41	 * mj1's migrated lane recorded a state, not a lane: no install, no build, no
42	 * inventory. It is superseded rather than corrected — it was true about the cell
43	 * it described.
44	 */
45	export const SUPERSEDES = Object.freeze({
46		record: 'mj1-migrated-lane.json',
47		unit: 'lrapr-t005/mj1-jira-clone-migration-lanes',
48		why: 'mj1 recorded the migrated lane as red at the closure install, with @ant-design/icons-angular@13.1.0 as the first unresolvable peer. The cell now declares the community layer that conflict came from, so the install this record describes is the same step mj1 attempted, on a manifest that resolves.',
49	});
50	
51	export type LockEntry = Readonly<{ path: string; url: string; integrity: string }>;
52	
53	/**
54	 * Every artifact the install acquired, read back out of the lockfile the install
55	 * wrote rather than out of a log: the lockfile is what the resolver committed
56	 * to, and it carries the integrity digest for each one.
57	 */
58	export function acquiredArtifacts(lockfile: string): readonly LockEntry[] {
59		const parsed: unknown = JSON.parse(lockfile);
60		if (typeof parsed !== 'object' || parsed === null)
61			throw new Error('Angular closure record: the lockfile is not a JSON object');
62		const packages = (parsed as Record<string, unknown>)['packages'];
63		if (typeof packages !== 'object' || packages === null)
64			throw new Error('Angular closure record: the lockfile declares no packages');
65		const entries: LockEntry[] = [];
66		for (const [key, value] of Object.entries(packages as Record<string, unknown>)) {
67			if (typeof value !== 'object' || value === null) continue;
68			const entry = value as Record<string, unknown>;
69			const url = entry['resolved'];
70			const integrity = entry['integrity'];
71			if (typeof url !== 'string' || typeof integrity !== 'string') continue;
72			entries.push({ path: key, url, integrity });
73		}
74		return Object.freeze(
75			entries.sort((left, right) => (left.path < right.path ? -1 : left.path > right.path ? 1 : 0)),
76		);
77	}
78	
79	/** Hosts the acquisition is allowed to have reached, as observed. */
80	export function acquisitionHosts(entries: readonly LockEntry[]): readonly string[] {
81		const hosts = new Set<string>();
82		for (const entry of entries) hosts.add(new URL(entry.url).host);
83		return Object.freeze([...hosts].sort());
84	}
85	
86	/**
87	 * The compiler's demands, itemised from the recorded build log.
88	 *
89	 * Each item names the file, the symbol, the library that moved and the transform
90	 * the demand asks for. The `observed` field is the compiler's own words, quoted
91	 * from the log this driver reads; everything else is this record's reading of
92	 * them, and is labelled as such rather than presented as compiler output.
93	 */
94	export type BuildDemand = Readonly<{
95		file: string;
96		symbol: string;
97		library: string;
98		observed: string;
99		neededTransform: string;
100	}>;
101	
102	export const BUILD_DEMANDS: readonly BuildDemand[] = Object.freeze([
103		Object.freeze({
104			file: 'src/main.ts',
105			symbol: "import { Integrations } from '@sentry/tracing'",
106			library: '@sentry/tracing → @sentry/angular 8',
107			observed:
108				"src/main.ts:4:30 - error TS2307: Cannot find module '@sentry/tracing' or its corresponding type declarations. / ./src/main.ts:4:0-47 - Error: Module not found: Error: Can't resolve '@sentry/tracing'",
109			neededTransform:
110				'The package was dropped by the cell as a no-successor package. The v8 SDK exposes tracing from @sentry/angular itself, so the import has to move and the `Integrations.BrowserTracing` construction it fed has to become the integration factory the v8 SDK exports.',
111		}),
112		Object.freeze({
113			file: 'src/main.ts',
114			symbol: 'Sentry.routingInstrumentation',
115			library: '@sentry/angular 6 → 8',
116			observed:
117				"src/main.ts:15:40 - error TS2339: Property 'routingInstrumentation' does not exist on type 'typeof import(\"@sentry/angular\")' / ./src/main.ts:13:30-59 - Error: export 'routingInstrumentation' (imported as 'Sentry') was not found in '@sentry/angular'",
118			neededTransform:
119				'The v8 SDK removed the standalone routing instrumentation hook; the browser tracing integration performs the routing instrumentation itself. The `routingInstrumentation` option passed into the tracing integration has to go, and whatever the v8 integration takes in its place has to be established from the library rather than guessed.',
120		}),
121		Object.freeze({
122			file: 'src/styles.scss',
123			symbol: "@import 'ng-zorro-antd/style/index.min.css' and eight sibling component imports",
124			library: 'ng-zorro-antd 13 → 16',
125			observed:
126				'./src/styles.scss - Error: Module build failed (from ./node_modules/css-loader/dist/cjs.js): Error: "./style/index.min.css" is not exported under the condition "style" from package .../node_modules/ng-zorro-antd (see exports field in .../ng-zorro-antd/package.json)',
127			neededTransform:
128				'ng-zorro-antd 16 publishes an `exports` map, and the era stylesheet paths are not in it under the `style` condition webpack resolves stylesheets with. Every one of the nine style imports has to be rewritten to a path the package exports, or the stylesheet entry point the package does export has to replace them.',
129		}),
130		Object.freeze({
131			file: 'node_modules/ng-zorro-antd/fesm2022/ng-zorro-antd-core-color.mjs and -core-config.mjs',
132			symbol: "import '@ctrl/tinycolor'",
133			library: 'ng-zorro-antd 16.2.2',
134			observed:
135				"./node_modules/ng-zorro-antd/fesm2022/ng-zorro-antd-core-color.mjs:1:0-65 - Error: Module not found: Error: Can't resolve '@ctrl/tinycolor'",
136			neededTransform:
137				'ng-zorro-antd 16.2.2 imports @ctrl/tinycolor from two of its own bundles but declares it in neither `dependencies` nor `peerDependencies`, so the resolved closure does not contain it. This is a demand of the library on its consumer, not of the application on itself: the manifest has to carry the package the library omitted, and that is a cell-level fact about ng-zorro-antd rather than a source transform.',
138		}),
139		Object.freeze({
140			file: 'src/app/project/components/issues/issue-card/issue-card.component.ts:45, src/app/project/components/issues/issue-detail/issue-detail.component.ts:31, src/app/project/components/search/search-drawer/search-drawer.component.ts:60',
141			symbol: 'nzComponentParams in NzModalService.create options',
142			library: 'ng-zorro-antd 13 → 16',
143			observed:
144				"error TS2345: Object literal may only specify known properties, and 'nzComponentParams' does not exist in type 'ModalOptions<…>'",
145			neededTransform:
146				'`ModalOptions.nzComponentParams` was removed from the ng-zorro-antd modal API. Three call sites pass component inputs through it. The replacement the library offers has to be read off the 16 API and applied at each site; the three sites are the same shape, so one transform covers them.',
147		}),
148	]);
149	
150	export const NOT_ESTABLISHED: readonly string[] = Object.freeze([
151		'The closure resolves and installs. That establishes nothing about whether the application compiles: it did not, and the demands above are why.',
152		'No migrated artifact exists, so there is still no build-level parity for this cell and no inventory to compare with the era lane.',
153		'No browser opened anything here. Nothing about behaviour, runtime parity or user-visible equivalence is observed.',
154		'The itemisation is this record’s reading of one build log on one host. A second host, or a later resolution of the same ranges, could surface demands this list does not carry.',
155		'The dropped packages are recorded as dropped. Nothing here establishes that the capabilities they provided — Sentry tracing, the Storybook analytics addon, the TSLint lint gate — are replaced, or that the application no longer needs them.',
156		'Nothing here is a production-readiness, pilot, certification or general Angular support claim.',
157	]);
158	
159	export const RECORDED_RISKS: readonly string[] = Object.freeze([
160		'The application initialises Sentry with a hard-coded DSN in src/main.ts. Its value is deliberately not reproduced anywhere in this evidence tree.',
161		'The application initialises Google Analytics with a hard-coded measurement id in src/app/core/services/google-analytics.service.ts. Its value is deliberately not reproduced anywhere in this evidence tree.',
162		'The install reached the public npm registry under the recorded consent and wrote 1,981 packages into a staged tree outside this repository. No package was executed beyond the lifecycle scripts npm runs on install, and no build product of that tree is committed here.',
163	]);
164	
165	export type SealedRecord = Readonly<Record<string, unknown>> & Readonly<{ digest: string }>;
166	
167	export function seal(body: Readonly<Record<string, unknown>>): SealedRecord {
168		return Object.freeze({ ...body, digest: sha256(canonical(body)) });
169	}
170	
171	export function verifySeal(record: SealedRecord): SealedRecord {
172		const { digest, ...body } = record;
173		const recomputed = sha256(canonical(body));
174		if (recomputed !== digest)
175			throw new Error(
176				`Angular jira-clone closure record digest differs: recorded ${digest}, recomputed ${recomputed}`,
177			);
178		return record;
179	}
180	
181	export function buildClosureRecord(input: {
182		manifest: string;
183		lockfile: string;
184		installExitStatus: number;
185		installStderrWarningKinds: readonly string[];
186		buildExitStatus: number;
187		buildErrorLines: readonly string[];
188		packagesAdded: number;
189	}): { closure: SealedRecord; acquisition: SealedRecord } {
190		const artifacts = acquiredArtifacts(input.lockfile);
191		const acquisition = seal({
192			schemaVersion: 'versionless.angular-jira-clone-acquired-closure.v1',
193			unit: UNIT,
194			consentId: CONSENT_ID,
195			meaning:
196				'Every artifact the migrated closure install acquired, with the URL it came from and the integrity digest the resolver committed to. Read back out of the lockfile the install wrote.',
197			networkMode: 'consented',
198			hosts: acquisitionHosts(artifacts),
199			count: artifacts.length,
200			artifacts,
201		});
202		const closure = seal({
203			schemaVersion: 'versionless.angular-jira-clone-migrated-closure.v1',
204			unit: UNIT,
205			consentId: CONSENT_ID,
206			result:
207				input.installExitStatus === 0
208					? input.buildExitStatus === 0
209						? 'closure-resolved-build-green'
210						: 'closure-resolved-build-red-itemised'
211					: 'closure-unresolved',
212			meaning:
213				'The migrated manifest the extended cell produces resolves and installs. The production build was then run once and is recorded as it happened: red, with every demand the compiler made itemised below. No source transform was attempted in this unit.',
214			supersedes: SUPERSEDES,
215			changeset: MIGRATION_RECORD_FILE,
216			cell: {
217				node: 'v16.20.2',
218				architecture: 'darwin-arm64, native — no translation layer',
219				npm: '8.19.4 (bundled with the runtime)',
220				builder: '@angular-devkit/build-angular:browser (Angular 16.2), the builder the absorption restored',
221				environment: { NG_CLI_ANALYTICS: 'false' },
222			},
223			acquisition: {
224				purpose: 'Install the declared Angular 16.2 dependency closure the migrated manifest asks for.',
225				consentId: CONSENT_ID,
226				networkMode: 'consented',
227				method:
228					'npm install --no-audit --no-fund (no lockfile carried over: the era lockfileVersion 2 pins the Angular 13 closure)',
