1	/**
2	 * The composed Angular CLI era migration: workspace configuration, TypeScript
3	 * configuration, package manifest and application source, lifted onto one
4	 * declared target cell and reported as a single itemised changeset.
5	 *
6	 * The changeset is the product. It records, per file, the bytes before and
7	 * after as digests and the individual changes that produced them, and it
8	 * separates application files from workspace files so that a count of changed
9	 * application files means what it says: source the application owns, changed by
10	 * a transform, not a version number edited in a manifest.
11	 */
12	
13	import { createHash } from 'node:crypto';
14	import {
15		alignAngularPackageManifest,
16		compareStrings,
17		type AngularTargetCell,
18		type DependencyChange,
19	} from './angular-target-cell.ts';
20	import { migrateAngularSourceModule, type SourceChange } from './angular-source-migration.ts';
21	import {
22		migrateModalContentParams,
23		type ModalContentParamsChange,
24		type ModuleResolution,
25	} from './modal-content-params-migration.ts';
26	import { migrateNgrxEffectDecorators, type NgrxEffectChange } from './ngrx-effects-migration.ts';
27	import {
28		migratePackageStyleImports,
29		type PackageExportsReading,
30		type StyleImportChange,
31	} from './package-exports-style-imports.ts';
32	import { migrateSentryV8Tracing, type SentryV8Change } from './sentry-v8-migration.ts';
33	import {
34		declareUndeclaredRuntimeDependencies,
35		undeclaredRuntimeDependencies,
36		type InstalledPackage,
37	} from './undeclared-runtime-dependency.ts';
38	import {
39		migrateAngularTsConfig,
40		migrateAngularWorkspace,
41		normalizeFragmentPath,
42		type ConfigChange,
43	} from './angular-workspace-migration.ts';
44	import { tslintConfigRemovals } from './tslint-toolchain-removal.ts';
45	
46	export type WorkspaceFile = Readonly<{ path: string; source: string }>;
47	
48	export type AngularMigrationInput = Readonly<{
49		packageManifest: WorkspaceFile;
50		workspaceConfig: WorkspaceFile;
51		tsConfig: WorkspaceFile;
52		/** Application source modules, as read from the workspace. */
53		sourceModules: readonly WorkspaceFile[];
54		/**
55		 * Webpack fragments a wrapper builder reads, keyed by the path the workspace
56		 * writes for them. A fragment a target references but that is not supplied
57		 * here is reported unread and its wrapper builder is left in place.
58		 */
59		webpackFragments?: readonly WorkspaceFile[];
60		/**
61		 * Every workspace-relative path the tree carries, for capabilities that
62		 * decide a file should no longer exist. Only paths are needed: a file removed
63		 * because the toolchain that read it is gone does not have to be parsed. A
64		 * tree that supplies no list has no files removed.
65		 */
66		workspaceFiles?: readonly string[];
67		/**
68		 * Stylesheets the application owns, kept apart from {@link sourceModules}
69		 * because they are not modules: no source transform parses them, and the only
70		 * capability that reads them resolves package subpaths against an exports map.
71		 */
72		styleSheets?: readonly WorkspaceFile[];
73		/**
74		 * The published surface of packages whose stylesheet subpaths the application
75		 * imports, as read from the installed closure. A package not read here has its
76		 * style imports left exactly as they are.
77		 */
78		packageExports?: readonly PackageExportsReading[];
79		/**
80		 * The installed dependency closure, reduced to declarations and shipped
81		 * imports. Supplying it is what lets undeclared runtime dependencies be
82		 * detected; a tree that supplies none has none detected, which is a different
83		 * thing from having none.
84		 */
85		installedPackages?: readonly InstalledPackage[];
86		/** How the workspace resolves module specifiers written in its own source. */
87		moduleResolution?: ModuleResolution;
88	}>;
89	
90	export type MigratedFile = Readonly<{
91		path: string;
92		kind: 'application' | 'workspace';
93		changed: boolean;
94		sha256Before: string;
95		sha256After: string;
96		source: string;
97		changes: readonly string[];
98	}>;
99	
100	export type AngularMigration = Readonly<{
101		cell: string;
102		files: readonly MigratedFile[];
103		applicationFilesChanged: number;
104		workspaceFilesChanged: number;
105		applicationFilesScanned: number;
106		unhandled: readonly string[];
107		/**
108		 * Capabilities the migrated workspace deliberately no longer has, one line
109		 * per removal — a dropped lint target, a dropped configuration file, a
110		 * package the cell read and found no successor for. A reader is owed these by
111		 * name: they are the difference between the era workspace and this one that a
112		 * clean changeset would otherwise hide.
113		 */
114		declaredDifferences: readonly string[];
115		/** Files the migration decided the tree should no longer carry. */
116		removedFiles: readonly string[];
117	}>;
118	
119	function sha256(value: string): string {
120		return createHash('sha256').update(value).digest('hex');
121	}
122	
123	function describeConfigChange(change: ConfigChange): string {
124		if (change.to === null) return `removed ${change.path} (was ${change.from ?? 'absent'})`;
125		if (change.from === null) return `added ${change.path} = ${change.to}`;
126		return `${change.path}: ${change.from} -> ${change.to}`;
127	}
128	
129	function describeDependencyChange(change: DependencyChange): string {
130		const target = `${change.field}.${change.name}`;
131		return change.to === null
132			? `removed ${target} (was ${change.from}) — ${change.reason}`
133			: `${target}: ${change.from} -> ${change.to} — ${change.reason}`;
134	}
135	
136	function describeSourceChange(
137		change:
138			| SourceChange
139			| NgrxEffectChange
140			| SentryV8Change
141			| ModalContentParamsChange
142			| StyleImportChange,
143	): string {
144		return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to}`;
145	}
146	
147	function file(
148		input: WorkspaceFile,
149		source: string,
150		kind: MigratedFile['kind'],
151		changes: readonly string[],
152	): MigratedFile {
153		return Object.freeze({
154			path: input.path,
155			kind,
156			changed: source !== input.source,
157			sha256Before: sha256(input.source),
158			sha256After: sha256(source),
159			source,
160			changes: Object.freeze([...changes]),
161		});
162	}
163	
164	/**
165	 * Apply every capability of the adapter to one workspace.
166	 *
167	 * Order matters in exactly one place: the workspace migration decides which
168	 * builder targets cannot be carried, and the packages those targets released
169	 * are what the manifest alignment then removes. Nothing else is ordered, and no
170	 * capability reads a file it was not handed.
171	 */
172	export function migrateAngularCliEraWorkspace(
173		input: AngularMigrationInput,
174		cell: AngularTargetCell,
175	): AngularMigration {
176		const unhandled: string[] = [];
177		const declaredDifferences: string[] = [];
178		const fragments: Record<string, string> = {};
179		for (const fragment of input.webpackFragments ?? [])
180			fragments[normalizeFragmentPath(fragment.path)] = fragment.source;
181		const workspace = migrateAngularWorkspace(input.workspaceConfig.source, cell, fragments);
182		unhandled.push(...workspace.unhandled);
183		declaredDifferences.push(...workspace.declaredDifferences);
184		const configRemovals = tslintConfigRemovals(input.workspaceFiles ?? [], cell);
185		declaredDifferences.push(...configRemovals.map((removal) => removal.reason));
186		for (const absorbed of workspace.absorbedFragments)
187			unhandled.push(
188				`${absorbed.path} was absorbed into the official builder and is no longer referenced by any ` +
189					`target; it was left in the tree rather than deleted. Absorbed capabilities: ` +
190					absorbed.capabilities.map((entry) => `${entry.kind} ${entry.detail}`).join(', '),
191			);
192		const manifest: unknown = JSON.parse(input.packageManifest.source);
193		if (typeof manifest !== 'object' || manifest === null || Array.isArray(manifest))
194			throw new Error('Angular migration: the package manifest is not a JSON object');
195		const aligned = alignAngularPackageManifest(
196			manifest as Readonly<Record<string, unknown>>,
197			cell,
198			workspace.removedPackages,
199		);
200		unhandled.push(...aligned.unhandled);
201		declaredDifferences.push(...aligned.declaredDifferences);
202		/**
203		 * Holes the closure carries are closed after the cell alignment, not before:
204		 * the cell decides which lines the workspace runs, and an undeclared edge is
205		 * declared at the line the cell read for it.
206		 */
207		const holes = undeclaredRuntimeDependencies(input.installedPackages ?? []);
208		const declared = declareUndeclaredRuntimeDependencies(aligned.manifest, holes, cell);
209		unhandled.push(...declared.unhandled);
210		declaredDifferences.push(...declared.declaredDifferences);
211		const tsConfig = migrateAngularTsConfig(input.tsConfig.source, cell);
212		unhandled.push(...tsConfig.unhandled);
213		const files: MigratedFile[] = [
214			file(
215				input.packageManifest,
216				`${JSON.stringify(declared.manifest, null, 2)}\n`,
217				'workspace',
218				[
219					...aligned.changes.map(describeDependencyChange),
220					...declared.declarations.map(
221						(entry) =>
222							`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
223					),
224				],
225			),
226			file(
227				input.workspaceConfig,
228				workspace.config,
229				'workspace',
230				workspace.changes.map(describeConfigChange),
231			),
232			file(
233				input.tsConfig,
234				tsConfig.config,
235				'workspace',
236				tsConfig.changes.map(describeConfigChange),
237			),
238		];
239		/**
240		 * Source capabilities run in sequence over each module, each one handed what
241		 * the last produced. They are independent — one rewrites module specifiers,
242		 * the next replaces a removed NgRx decorator — and a module is counted as
243		 * changed if any of them changed a byte of it.
244		 */
245		/**
246		 * One capability is not per-module and cannot be: rewriting a modal call site
247		 * without rewriting the content component it supplied is the silent failure
248		 * that capability exists to refuse. It runs over the whole tree first, and
249		 * what it produced is what the per-module capabilities then see.
250		 */
251		const modal = migrateModalContentParams(input.sourceModules, input.moduleResolution ?? {});
252		unhandled.push(...modal.unhandled);
253		const modalByPath = new Map(modal.files.map((entry) => [entry.path, entry]));
254		for (const module of [...input.sourceModules].sort((left, right) =>
255			compareStrings(left.path, right.path),
256		)) {
257			const modalFile = modalByPath.get(module.path);
258			const entrySource = modalFile?.source ?? module.source;
259			const migrated = migrateAngularSourceModule(module.path, entrySource);
260			const effects = migrateNgrxEffectDecorators(module.path, migrated.source);
261			const sentry = migrateSentryV8Tracing(module.path, effects.source);
262			unhandled.push(...migrated.unhandled, ...effects.unhandled, ...sentry.unhandled);
263			files.push(
264				file(module, sentry.source, 'application', [
265					...(modalFile?.changes ?? []).map(describeSourceChange),
266					...migrated.changes.map(describeSourceChange),
267					...effects.changes.map(describeSourceChange),
268					...sentry.changes.map(describeSourceChange),
269				]),
270			);
271		}
272		/**
273		 * Stylesheets are application files too, and a blocked package subpath is an
274		 * application file that no longer builds. Each is offered to every package
275		 * reading the caller supplied; a stylesheet no reading touches is carried
276		 * through unchanged and still counted, so the scanned total means what it says.
277		 */
278		for (const sheet of [...(input.styleSheets ?? [])].sort((left, right) =>
279			compareStrings(left.path, right.path),
280		)) {
281			let source = sheet.source;
282			const changes: string[] = [];
283			for (const reading of input.packageExports ?? []) {
284				const styles = migratePackageStyleImports(sheet.path, source, reading);
285				unhandled.push(...styles.unhandled);
286				declaredDifferences.push(...styles.declaredDifferences);
287				changes.push(...styles.changes.map(describeSourceChange));
288				source = styles.source;
289			}
290			files.push(file(sheet, source, 'application', changes));
291		}
292		const applicationFiles = files.filter((entry) => entry.kind === 'application');
293		return Object.freeze({
294			cell: cell.id,
295			files: Object.freeze(files),
296			applicationFilesChanged: applicationFiles.filter((entry) => entry.changed).length,
297			workspaceFilesChanged: files.filter((entry) => entry.kind === 'workspace' && entry.changed)
298				.length,
299			applicationFilesScanned: applicationFiles.length,
300			unhandled: Object.freeze([...new Set(unhandled)]),
301			declaredDifferences: Object.freeze([...new Set(declaredDifferences)]),
302			removedFiles: Object.freeze(configRemovals.map((removal) => removal.at)),
303		});
304	}
