1	/**
2	 * Undeclared runtime dependencies — peer holes — read out of an installed
3	 * dependency closure and closed in the application's own manifest.
4	 *
5	 * A published package states its runtime edges in `dependencies` and
6	 * `peerDependencies`. When the bundles it actually ships import a package it
7	 * declares in neither, the edge exists but nothing in the closure is obliged to
8	 * satisfy it. An installation that works anyway works by accident: some other
9	 * package happened to hoist the module to a place the resolver found. Nothing
10	 * records that, so nothing preserves it, and the first unrelated dependency
11	 * change breaks a build for a reason the manifest cannot explain.
12	 *
13	 * The detection is entirely a reading of the closure's own facts:
14	 *
15	 * - what each installed package's manifest declares, and
16	 * - what each installed package's shipped bundles import.
17	 *
18	 * Nothing here knows which packages have holes. The pair (importer, imported)
19	 * is discovered, never listed. What the capability will not invent is the
20	 * *version*: the range comes from the target cell's community-layer reading,
21	 * chosen by the same mechanical rule every other entry in that table was chosen
22	 * by, and a hole the cell has read no line for is reported rather than guessed
23	 * at. Declaring a dependency at a version nobody read would replace an accident
24	 * with a fabrication.
25	 *
26	 * What closing a hole establishes is narrow, and the reason recorded with the
27	 * change says so: the application now declares an edge the closure previously
28	 * supplied by accident. It does not establish that the declared line's export
29	 * surface matches what the importer's bundles reach for — a build, and then a
30	 * witness, arbitrate that.
31	 */
32	
33	import { builtinModules } from 'node:module';
34	import {
35		compareStrings,
36		ecosystemDispositionOf,
37		type AngularTargetCell,
38		type PackageManifest,
39	} from './angular-target-cell.ts';
40	import { parseModule, type AstNode } from './semantic-module.ts';
41	
42	/** The manifest fields that declare an edge a runtime import may rely on. */
43	export const RUNTIME_DEPENDENCY_FIELDS: readonly string[] = Object.freeze([
44		'dependencies',
45		'peerDependencies',
46		'optionalDependencies',
47	]);
48	
49	/** The manifest fields an application may already close a hole in. */
50	const APPLICATION_DEPENDENCY_FIELDS: readonly string[] = Object.freeze([
51		'dependencies',
52		'devDependencies',
53	]);
54	
55	const NODE_BUILTINS: ReadonlySet<string> = new Set(builtinModules);
56	
57	/** One file of a published package, as installed. */
58	export type InstalledFile = Readonly<{ path: string; source: string }>;
59	
60	/** One bare specifier a package's shipped bundles import, and where from. */
61	export type PackageImport = Readonly<{ specifier: string; from: string }>;
62	
63	/** One installed package, reduced to the two facts the detection needs. */
64	export type InstalledPackage = Readonly<{
65		name: string;
66		version: string;
67		/** Package names declared in any of {@link RUNTIME_DEPENDENCY_FIELDS}. */
68		declared: readonly string[];
69		/** Bare specifiers the shipped bundles import, with the file each came from. */
70		imports: readonly PackageImport[];
71	}>;
72	
73	export type UndeclaredRuntimeDependency = Readonly<{
74		/** The package whose bundles import without declaring. */
75		importer: string;
76		importerVersion: string;
77		/** The package name the bundles reach for. */
78		dependency: string;
79		/** The specifiers, deduplicated and sorted, that produced the hole. */
80		specifiers: readonly string[];
81		/** The shipped files, deduplicated and sorted, the specifiers were read in. */
82		files: readonly string[];
83		/**
84		 * Whether some package in the closure happens to carry the name anyway. A
85		 * hole is a hole either way — the point is that nothing declared the edge —
86		 * but a hole that is currently unsatisfied is also a build that cannot run.
87		 */
88		satisfiedByClosure: boolean;
89	}>;
90	
91	/**
92	 * The package a bare module specifier names, or null when the specifier does
93	 * not name one: a relative or absolute path, a protocol-qualified specifier, or
94	 * a Node builtin, none of which a manifest is expected to declare.
95	 */
96	export function packageNameOfSpecifier(specifier: string): string | null {
