118	/** The module specifier of a re-export declaration, when it has one. */
119	function reexportSpecifier(node: AstNode): string | null {
120		if (node.type !== 'ExportAllDeclaration' && node.type !== 'ExportNamedDeclaration') return null;
121		const source = node.source;
122		if (source === null || source === undefined || source.type !== 'Literal') return null;
123		return typeof source.value === 'string' ? source.value : null;
