127	 * Read one installed package into the facts the detection needs.
128	 *
129	 * The bundles are parsed, not scanned for text: a specifier is a specifier
130	 * because the module graph says so, not because the bytes of a comment or a
131	 * string constant happened to spell one. Static imports, re-exports and
132	 * dynamic imports with a literal specifier all count, because all three are
133	 * runtime edges the package's own code makes.
134	 */
135	export function readInstalledPackage(
136		manifestSource: string,
137		bundles: readonly InstalledFile[],
138	): InstalledPackage {
139		const parsed: unknown = JSON.parse(manifestSource);
140		if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))
141			throw new Error('Undeclared runtime dependency reading: a package manifest is not an object');
