193					Object.freeze({
194						importer: importer.name,
195						importerVersion: importer.version,
196						dependency,
197						specifiers: Object.freeze([...entry.specifiers].sort(compareStrings)),
198						files: Object.freeze([...entry.files].sort(compareStrings)),
199						satisfiedByClosure: installed.has(dependency),
200					}),
201				);
202			}
203		}
204		return Object.freeze(
205			holes.sort(
206				(left, right) =>
207					compareStrings(left.dependency, right.dependency) ||
208					compareStrings(left.importer, right.importer),
209			),
210		);
211	}
