1	/**
2	 * Stylesheet imports a package's `exports` map no longer resolves.
3	 *
4	 * A package that adds an `exports` field stops being a directory and becomes a
5	 * declared surface: every subpath it does not name is unreachable, whatever the
6	 * bytes on disk are. Libraries that publish per-component stylesheets alongside
7	 * whole-library aggregates routinely name the component subpaths and not the
8	 * root one, so an application that imported the root entry finds exactly that
9	 * one import blocked while its neighbours keep resolving.
10	 *
11	 * There is no narrow successor for a blocked root entry. The package exports an
12	 * aggregate — the whole library's stylesheet — or it exports nothing this
13	 * capability can put in the blocked import's place, and in that second case it
14	 * refuses and leaves the import exactly as it is.
15	 *
16	 * When an aggregate does exist, the rewrite is a substitution, not a repair:
17	 *
18	 * ```scss
19	 * ⁠@import 'pkg/style/index.min.css';          ⁠@import 'pkg/pkg.min.css';
20	 * ⁠@import 'pkg/tooltip/style/index.min.css';
21	 * ⁠@import 'pkg/modal/style/index.min.css';    ->
22	 * ```
23	 *
24	 * The aggregate contains every component stylesheet, so the granular imports of
25	 * the same package become redundant and are removed — each removal recorded by
26	 * name. The migrated application therefore ships the package's entire
27	 * stylesheet where it previously shipped a chosen subset. That is a payload
28	 * change, and it is reported through the changeset's declared-differences
29	 * channel with the byte counts named whenever the closure was measured, because
30	 * a substitution that quietly multiplies a CSS payload is exactly the kind of
31	 * difference a clean-looking changeset would otherwise hide. Parity carries it
32	 * as a non-claim; a witness arbitrates whether the application still looks and
33	 * behaves as it did.
34	 */
35	
36	import { charIn, charNotIn, createRegExp, exactly, global, maybe, oneOrMore } from 'magic-regexp';
37	import { compareStrings } from './angular-target-cell.ts';
38	import { lineOf, applySourceEdits, type SourceEdit } from './semantic-module.ts';
39	
40	/**
41	 * The export conditions a stylesheet import is resolved under. `style` is the
42	 * condition a CSS consumer sets; `default` is the unconditional fallback every
43	 * exports map may carry.
44	 */
45	export const STYLE_EXPORT_CONDITIONS: readonly string[] = Object.freeze(['style', 'default']);
46	
47	/** A package's published surface, as read from the installed closure. */
48	export type PackageExportsReading = Readonly<{
49		name: string;
50		version: string;
51		/** The `exports` field exactly as the package published it. */
52		exports: unknown;
53		/**
54		 * Byte size per package-relative file path, when the closure was measured.
55		 * Supplying it is what lets the payload change be named in bytes rather than
56		 * in words; omitting it costs the numbers, not the report.
57		 */
58		fileSizes?: Readonly<Record<string, number>>;
59	}>;
60	
61	export type StyleImportChange = Readonly<{
62		kind: 'style-import-aggregate' | 'style-import-redundant';
63		line: number;
64		from: string;
65		to: string;
66	}>;
67	
68	export type StyleImportMigration = Readonly<{
69		path: string;
70		source: string;
71		changed: boolean;
72		changes: readonly StyleImportChange[];
73		declaredDifferences: readonly string[];
74		unhandled: readonly string[];
75	}>;
76	
77	const STYLE_IMPORT = createRegExp(
78		exactly('@import')
79			.and(oneOrMore(charIn(' \t')))
80			.and(charIn('\'"'))
81			.and(oneOrMore(charNotIn('\'"\n')).as('specifier'))
82			.and(charIn('\'"'))
83			.and(maybe(oneOrMore(charIn(' \t'))))
84			.and(maybe(exactly(';'))),
85		[global],
86	);
87	
88	type ExportsObject = Readonly<Record<string, unknown>>;
89	
90	function asObject(value: unknown): ExportsObject | null {
91		return typeof value === 'object' && value !== null && !Array.isArray(value)
92			? (value as ExportsObject)
93			: null;
94	}
95	
96	/**
97	 * Resolve one target of an exports map under a condition list. A string is the
98	 * target; an object is a condition map, taken in declaration order; an array is
99	 * a fallback list, taken left to right; `null` is an explicit block.
100	 */
101	function resolveTarget(
102		target: unknown,
103		conditions: readonly string[],
104		star: string | null,
105	): string | null {
106		if (typeof target === 'string')
107			return star === null ? target : target.split('*').join(star);
108		if (Array.isArray(target)) {
109			for (const entry of target as readonly unknown[]) {
110				const resolved = resolveTarget(entry, conditions, star);
111				if (resolved !== null) return resolved;
112			}
113			return null;
114		}
115		const object = asObject(target);
116		if (object === null) return null;
117		for (const [condition, value] of Object.entries(object)) {
118			if (condition !== 'default' && !conditions.includes(condition)) continue;
119			const resolved = resolveTarget(value, conditions, star);
120			if (resolved !== null) return resolved;
121		}
122		return null;
123	}
124	
125	/**
126	 * The file a package's `exports` field resolves `subpath` to under
127	 * `conditions`, or null when the map does not expose it at all. Exact keys win
128	 * over patterns, and among patterns the longest literal prefix wins — the
129	 * resolution algorithm the runtime itself uses.
130	 */
131	export function resolvePackageExport(
132		exportsField: unknown,
133		subpath: string,
134		conditions: readonly string[] = STYLE_EXPORT_CONDITIONS,
135	): string | null {
136		if (exportsField === undefined || exportsField === null) return null;
137		if (typeof exportsField === 'string' || Array.isArray(exportsField))
138			return subpath === '.' ? resolveTarget(exportsField, conditions, null) : null;
139		const map = asObject(exportsField);
140		if (map === null) return null;
141		const keys = Object.keys(map);
142		const isSubpathMap = keys.length > 0 && keys.every((key) => key.startsWith('.'));
143		if (!isSubpathMap) return subpath === '.' ? resolveTarget(map, conditions, null) : null;
144		if (subpath in map) return resolveTarget(map[subpath], conditions, null);
145		let bestPrefix: string | null = null;
146		let bestStar: string | null = null;
147		for (const key of keys) {
148			const starIndex = key.indexOf('*');
149			if (starIndex < 0) continue;
150			const prefix = key.slice(0, starIndex);
151			const suffix = key.slice(starIndex + 1);
152			if (suffix.includes('*')) continue;
153			if (!subpath.startsWith(prefix) || !subpath.endsWith(suffix)) continue;
154			if (subpath.length < prefix.length + suffix.length) continue;
155			if (bestPrefix !== null && prefix.length <= bestPrefix.length) continue;
156			bestPrefix = key;
157			bestStar = subpath.slice(prefix.length, subpath.length - suffix.length);
158		}
159		if (bestPrefix === null) return null;
160		return resolveTarget(map[bestPrefix], conditions, bestStar);
161	}
162	
163	/** The package a stylesheet specifier names, and the subpath it asks that package for. */
164	function splitSpecifier(specifier: string): Readonly<{ name: string; subpath: string }> | null {
165		if (specifier === '' || specifier.startsWith('.') || specifier.startsWith('/')) return null;
166		if (specifier.includes(':')) return null;
167		const trimmed = specifier.startsWith('~') ? specifier.slice(1) : specifier;
168		const segments = trimmed.split('/');
169		const first = segments[0];
170		if (first === undefined || first === '') return null;
171		const consumed = first.startsWith('@') ? 2 : 1;
172		const name = segments.slice(0, consumed).join('/');
173		if (consumed === 2 && (segments[1] === undefined || segments[1] === '')) return null;
174		const rest = segments.slice(consumed).join('/');
175		return Object.freeze({ name, subpath: rest === '' ? '.' : `./${rest}` });
176	}
177	
178	/**
179	 * The extension chain of a subpath's file name: everything from its first dot.
180	 * `./style/index.min.css` carries `.min.css`, and a minified entry is replaced
181	 * by a minified aggregate rather than silently by an unminified one.
182	 */
183	function extensionChainOf(subpath: string): string | null {
184		const fileName = subpath.slice(subpath.lastIndexOf('/') + 1);
185		const dot = fileName.indexOf('.');
186		return dot <= 0 ? null : fileName.slice(dot);
187	}
188	
189	/**
190	 * The package's exported root aggregate stylesheet for a blocked import, or
191	 * null when it publishes none.
192	 *
193	 * The aggregate is identified mechanically and not by a list: it is the exports
194	 * key that sits at the package root, is spelled with the package's own
195	 * unscoped name, carries the same extension chain the blocked import asked for,
196	 * and resolves under the style conditions. A themed or otherwise qualified
197	 * sibling — one whose stem is the package name plus something else — is a
198	 * different stylesheet, not the aggregate, and is never substituted.
199	 */
200	export function rootAggregateStylesheet(
201		reading: PackageExportsReading,
202		blockedSubpath: string,
203	): Readonly<{ subpath: string; file: string }> | null {
204		const extension = extensionChainOf(blockedSubpath);
205		if (extension === null) return null;
206		const unscoped = reading.name.slice(reading.name.lastIndexOf('/') + 1);
207		const subpath = `./${unscoped}${extension}`;
208		const map = asObject(reading.exports);
209		if (map === null || !(subpath in map)) return null;
210		const file = resolvePackageExport(reading.exports, subpath, STYLE_EXPORT_CONDITIONS);
211		return file === null ? null : Object.freeze({ subpath, file });
212	}
213	
214	type Site = Readonly<{
215		start: number;
216		end: number;
217		specifier: string;
218		specifierStart: number;
219		subpath: string;
220		line: number;
221		resolved: string | null;
222	}>;
223	
224	function packageRelative(subpath: string): string {
225		return subpath.startsWith('./') ? subpath.slice(2) : subpath;
226	}
227	
228	function sizeOf(reading: PackageExportsReading, file: string | null): number | null {
229		if (file === null) return null;
230		const sizes = reading.fileSizes;
231		if (sizes === undefined) return null;
232		const size = sizes[packageRelative(file)];
233		return typeof size === 'number' ? size : null;
234	}
235	
236	/**
237	 * Rewrite one stylesheet's imports of a package whose exports map blocks them.
238	 *
239	 * A stylesheet with no import of the package, or whose every import of it
240	 * resolves, is returned byte-identical and reports nothing: an exports map that
241	 * still exposes what the application asked for is not this capability's
242	 * business.
243	 */
244	export function migratePackageStyleImports(
245		path: string,
246		source: string,
247		reading: PackageExportsReading,
248	): StyleImportMigration {
249		const unchanged = (unhandled: readonly string[] = []): StyleImportMigration =>
250			Object.freeze({
251				path,
252				source,
253				changed: false,
254				changes: Object.freeze([]),
255				declaredDifferences: Object.freeze([]),
256				unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
257			});
258		const sites: Site[] = [];
259		for (const match of source.matchAll(STYLE_IMPORT)) {
260			const specifier = match.groups?.['specifier'];
261			const start = match.index;
262			const matched = match[0];
263			if (specifier === undefined || start === undefined || matched === undefined) continue;
264			const split = splitSpecifier(specifier);
265			if (split === null || split.name !== reading.name) continue;
266			sites.push(
267				Object.freeze({
268					start,
269					end: start + matched.length,
270					specifier,
271					specifierStart: source.indexOf(specifier, start),
272					subpath: split.subpath,
273					line: lineOf(source, start),
274					resolved: resolvePackageExport(reading.exports, split.subpath, STYLE_EXPORT_CONDITIONS),
275				}),
276			);
277		}
278		if (sites.length === 0) return unchanged();
279		const blocked = sites.filter((site) => site.resolved === null);
280		if (blocked.length === 0) return unchanged();
281		const first = blocked[0] as Site;
282		const aggregate = rootAggregateStylesheet(reading, first.subpath);
283		if (aggregate === null)
284			return unchanged(
285				blocked.map(
286					(site) =>
287						`${path} line ${site.line}: ${reading.name}@${reading.version} does not expose ` +
288						`${site.subpath} through its exports map and publishes no root aggregate stylesheet ` +
289						'to put in its place, so the import was left exactly as it is',
290				),
291			);
292		const aggregateSpecifier = `${reading.name}/${packageRelative(aggregate.subpath)}`;
293		const edits: SourceEdit[] = [
294			{
295				start: first.specifierStart,
296				end: first.specifierStart + first.specifier.length,
297				text: aggregateSpecifier,
298			},
299		];
300		const changes: StyleImportChange[] = [
301			{
302				kind: 'style-import-aggregate',
303				line: first.line,
304				from: first.specifier,
305				to: aggregateSpecifier,
306			},
307		];
308		const removed = sites.filter((site) => site !== first);
309		for (const site of removed) {
310			let end = site.end;
311			while (source[end] === ' ' || source[end] === '\t') end += 1;
312			if (source[end] === '\r') end += 1;
313			if (source[end] === '\n') end += 1;
314			edits.push({ start: site.start, end, text: '' });
315			changes.push({
316				kind: 'style-import-redundant',
317				line: site.line,
318				from: site.specifier,
319				to: aggregateSpecifier,
320			});
321		}
322		const aggregateBytes = sizeOf(reading, aggregate.file);
323		const replacedBytes = [first, ...removed].reduce<number | null>((total, site) => {
324			if (total === null) return null;
325			const size = sizeOf(reading, site.resolved ?? site.subpath);
326			return size === null ? null : total + size;
327		}, 0);
328		const payload =
329			aggregateBytes === null || replacedBytes === null
330				? 'The migrated application ships the package\'s whole stylesheet where it previously ' +
331					'shipped the subset it named; the closure was not measured, so the change is not ' +
332					'stated in bytes here.'
333				: `The migrated application ships ${aggregateBytes} bytes of stylesheet where it ` +
334					`previously shipped ${replacedBytes}.`;
335		const declaredDifferences: string[] = [
336			`${path}: ${sites.length} ${reading.name} stylesheet import(s) were replaced by the single ` +
337				`exported aggregate ${aggregateSpecifier}, because ${reading.name}@${reading.version} ` +
338				`does not expose ${first.subpath} through its exports map and publishes no narrower ` +
339				`equivalent. ${payload} This changeset makes no claim that the application renders as it ` +
340				'did; a witness arbitrates that.',
341		];
342		for (const site of removed)
343			declaredDifferences.push(
344				`${path} line ${site.line}: the granular import ${site.specifier} was removed. It is ` +
345					`contained in the aggregate ${aggregateSpecifier} that replaced the blocked root ` +
346					'import, so keeping it would import the same rules twice.',
347			);
348		const migrated = applySourceEdits(source, edits);
349		return Object.freeze({
350			path,
351			source: migrated,
352			changed: migrated !== source,
353			changes: Object.freeze(changes),
354			declaredDifferences: Object.freeze(declaredDifferences),
355			unhandled: Object.freeze([]),
356		});
357	}
