1	/**
2	 * Record the two build lanes of the `angular-factoriolab` migration cell.
3	 *
4	 * Lane one is the era baseline: the pinned tree on its own cell — Rosetta x64
5	 * Node 12.14.1, the era dependency closure, `ng build --prod` — rebuilt twice
6	 * to see whether the restored cache still produces the same bytes.
7	 *
8	 * Lane two is the migrated tree: the adapter's composed changeset applied to
9	 * the same pinned tree, the declared Angular 16.2 closure installed, and the
10	 * official `@angular-devkit/build-angular:browser` builder run twice under
11	 * native Node 16.20.2.
12	 *
13	 * What this driver records is build-level only: which files each lane emitted,
14	 * their digests and sizes, and where the two inventories agree and differ. It
15	 * observes no browser and asserts no behavioural equivalence; a difference
16	 * found here is recorded as a difference, never as a defect and never as a
17	 * pass.
18	 *
19	 * The driver is fixture-scoped — it knows where this fixture's lanes were
20	 * materialised — while every decision about *what to change* lives in
21	 * `@versionless/angular`, which knows nothing about this application.
22	 */
23	
24	import { readFile, readdir, mkdir, writeFile } from 'node:fs/promises';
25	import * as path from 'pathe';
26	import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
27	
28	const repositoryRoot = path.resolve(import.meta.dirname, '../../../..');
29	const evidenceDirectory = path.join(repositoryRoot, 'evidence/runs/angular-factoriolab');
30	
31	export const ERA_REBUILD_DIRECTORY = path.join(
32		repositoryRoot,
33		'.versionless/cache/angular-factoriolab-baseline/rebuild',
34	);
35	export const MIGRATED_STAGE_DIRECTORY = path.join(
36		repositoryRoot,
37		'.versionless/stage/angular-factoriolab-m2',
38	);
39	
40	export type DistEntry = Readonly<{ path: string; sha256: string; bytes: number }>;
41	
42	/** Every file below `directory`, digested, ordered by path. */
43	export async function inventoryOf(directory: string): Promise<DistEntry[]> {
44		const entries: DistEntry[] = [];
45		const walk = async (current: string): Promise<void> => {
46			for (const item of await readdir(current, { withFileTypes: true })) {
47				const full = path.join(current, item.name);
48				if (item.isDirectory()) {
49					await walk(full);
50					continue;
51				}
52				if (!item.isFile()) continue;
53				const bytes = await readFile(full);
54				entries.push({
55					path: path.relative(directory, full).split(path.sep).join('/'),
56					sha256: sha256(bytes.toString('binary')),
57					bytes: bytes.byteLength,
58				});
59			}
60		};
61		await walk(directory);
62		return entries.sort((left, right) => (left.path < right.path ? -1 : 1));
63	}
64	
65	/**
66	 * Strip the content hash the Angular CLI stamps into an emitted file name, so
67	 * `main-es2015.eea9ba8e….js` and `main.67d430ec….js` can be recognised as the
68	 * same emission point across two builders that hash differently. The era line's
69	 * differential-loading suffix is stripped with it, and reported separately by
70	 * {@link compareInventories} so that removing it is never silent.
71	 */
72	export function emissionPointOf(file: string): string {
73		const directory = file.includes('/') ? `${file.slice(0, file.lastIndexOf('/'))}/` : '';
74		const name = file.slice(directory.length);
75		const withoutHash = name.replace(/\.[0-9a-f]{16,32}(?=\.[^.]+$)/, '');
76		return `${directory}${withoutHash.replace(/-es(5|2015)(?=\.[^.]+$)/, '')}`;
77	}
78	
79	export type ParityEntry = Readonly<{
80		emissionPoint: string;
81		era: readonly DistEntry[];
82		migrated: readonly DistEntry[];
83		/** Identical bytes in both lanes, whatever the file was named. */
84		bytesIdentical: boolean;
85		/** Total migrated bytes minus total era bytes at this emission point. */
86		byteDelta: number;
87	}>;
88	
89	export type Parity = Readonly<{
90		eraFileCount: number;
91		migratedFileCount: number;
92		entries: readonly ParityEntry[];
93		onlyInEra: readonly string[];
94		onlyInMigrated: readonly string[];
95		identicalPayloads: readonly string[];
96	}>;
97	
98	/**
99	 * Line the two inventories up by emission point.
100	 *
101	 * Matching on the emission point rather than the file name is the only way to
102	 * compare across the hop at all: both builders hash their output into the file
103	 * name, so every emitted bundle is named differently in the two lanes even when
104	 * its content is byte-identical. An emission point present in one lane and not
105	 * the other is reported by name rather than folded into a total.
106	 */
107	export function compareInventories(era: readonly DistEntry[], migrated: readonly DistEntry[]): Parity {
108		const group = (entries: readonly DistEntry[]): Map<string, DistEntry[]> => {
109			const grouped = new Map<string, DistEntry[]>();
110			for (const entry of entries) {
111				const key = emissionPointOf(entry.path);
112				grouped.set(key, [...(grouped.get(key) ?? []), entry]);
113			}
114			return grouped;
115		};
116		const eraGroups = group(era);
117		const migratedGroups = group(migrated);
118		const points = [...new Set([...eraGroups.keys(), ...migratedGroups.keys()])].sort();
119		const entries: ParityEntry[] = [];
120		const identicalPayloads: string[] = [];
121		const onlyInEra: string[] = [];
122		const onlyInMigrated: string[] = [];
123		for (const point of points) {
124			const left = eraGroups.get(point) ?? [];
125			const right = migratedGroups.get(point) ?? [];
126			if (right.length === 0) onlyInEra.push(point);
127			if (left.length === 0) onlyInMigrated.push(point);
128			const leftDigests = new Set(left.map((entry) => entry.sha256));
129			const bytesIdentical =
130				left.length > 0 && right.length > 0 && right.every((entry) => leftDigests.has(entry.sha256));
131			if (bytesIdentical) identicalPayloads.push(point);
132			const total = (group: readonly DistEntry[]): number =>
133				group.reduce((sum, entry) => sum + entry.bytes, 0);
134			entries.push({
135				emissionPoint: point,
136				era: Object.freeze(left),
137				migrated: Object.freeze(right),
138				bytesIdentical,
139				byteDelta: total(right) - total(left),
140			});
141		}
142		return Object.freeze({
143			eraFileCount: era.length,
144			migratedFileCount: migrated.length,
145			entries: Object.freeze(entries),
146			onlyInEra: Object.freeze(onlyInEra),
147			onlyInMigrated: Object.freeze(onlyInMigrated),
148			identicalPayloads: Object.freeze(identicalPayloads),
149		});
150	}
151	
152	export type SealedRecord = Readonly<Record<string, unknown>> & Readonly<{ digest: string }>;
153	
154	/** Seal a record body with a digest recomputable from its own canonical form. */
155	export function sealRecord(body: Readonly<Record<string, unknown>>): SealedRecord {
156		return Object.freeze({ ...body, digest: sha256(canonical(body)) });
157	}
158	
159	/** Recompute a sealed record's digest; a record that does not seal is rejected. */
160	export function verifySealedRecord(record: SealedRecord): SealedRecord {
161		const { digest, ...body } = record;
162		const recomputed = sha256(canonical(body));
163		if (recomputed !== digest)
164			throw new Error(
165				`Angular factoriolab build-lane record digest differs: recorded ${digest}, recomputed ${recomputed}`,
166			);
167		return record;
168	}
169	
170	/**
171	 * Two inventories of the same lane, taken from two consecutive builds. Equal
172	 * inventories are the only evidence of determinism this driver accepts; a
173	 * single build proves nothing about repeatability and is never reported as if
174	 * it did.
175	 */
176	export function isByteStable(first: readonly DistEntry[], second: readonly DistEntry[]): boolean {
177		return canonical(first) === canonical(second);
178	}
179	
180	const UNIT = 'lrapr-t005/m2-factoriolab-build-lanes';
181	const CONSENT = 'VL-LEGACY-CORPUS-2026-08-10';
182	
183	async function readText(file: string): Promise<string> {
184		return await readFile(file, 'utf8');
185	}
186	
187	export async function main(): Promise<void> {
188		const eraFirst = await inventoryOf(path.join(ERA_REBUILD_DIRECTORY, 'dist-1'));
189		const eraSecond = await inventoryOf(path.join(ERA_REBUILD_DIRECTORY, 'dist-2'));
190		const eraIngest = await inventoryOf(
191			path.join(
192				repositoryRoot,
193				'.versionless/cache/angular-factoriolab-baseline/app/dist-a1',
194			),
195		);
196		const migratedFirst = await inventoryOf(path.join(MIGRATED_STAGE_DIRECTORY, 'dist-a'));
197		const migratedSecond = await inventoryOf(path.join(MIGRATED_STAGE_DIRECTORY, 'dist-b'));
198		const lock: unknown = JSON.parse(
199			await readText(path.join(MIGRATED_STAGE_DIRECTORY, 'migrated/package-lock.json')),
200		);
201		const packages = Object.entries(
202			(lock as { packages: Record<string, { resolved?: string; integrity?: string }> }).packages,
203		).filter(([name]) => name !== '');
204		const hosts = [
205			...new Set(
206				packages
207					.map(([, entry]) => entry.resolved)
208					.filter((url): url is string => typeof url === 'string')
209					.map((url) => new URL(url).host),
210			),
211		].sort();
212		await mkdir(evidenceDirectory, { recursive: true });
213	
214		const era = sealRecord({
215			schemaVersion: 'versionless.angular-factoriolab-era-baseline.v1',
216			unit: UNIT,
217			consentId: CONSENT,
218			result: eraFirst.length > 0 && isByteStable(eraFirst, eraSecond) ? 'byte-stable' : 'unstable',
219			cell: {
220				node: 'v12.14.1',
221				architecture: 'darwin-x64 under Rosetta 2 on an arm64 host (arch -x86_64)',
222				npm: '6.13.4',
223				command: 'npm run build -- --prod',
224				builder: '@angular-devkit/build-angular:browser (Angular CLI 10.1.x)',
225			},
226			source: {
227				cache: '.versionless/cache/angular-factoriolab-baseline',
228				provenance:
229					'Restored by the PM from the a1 ingest worktree: the installed era closure and the 26 oid-verified Git LFS payloads the pinned tree carries as pointer stubs.',
230				deviation:
231					'The pinned tree cannot build unmodified: src/data/** is Git LFS, and its 26 pointer stubs fail the production build on TS1136. The labelled deviation a1 recorded — materialise the 26 payloads, each verified against the pointer oid — is carried into this lane unchanged.',
232			},
233			builds: [
234				{ run: 1, status: 0, files: eraFirst.length },
235				{ run: 2, status: 0, files: eraSecond.length },
236			],
237			byteStable: isByteStable(eraFirst, eraSecond),
238			reproducesIngestBuild: isByteStable(eraFirst, eraIngest),
239			inventory: eraFirst,
240			notEstablished: [
